package com.bank.statement;

import java.math.BigDecimal;
import java.util.logging.*;

public class PrefixSumDemo {
    private static final Logger log = Logger.getLogger(PrefixSumDemo.class.getName());

    static {
        LogManager.getLogManager().reset();
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        log.addHandler(handler);
        log.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        // Rajesh daily transaction amounts (days 0..6)
        BigDecimal[] daily = {
            new BigDecimal("1000"), new BigDecimal("2000"), new BigDecimal("1500"),
            new BigDecimal("3000"), new BigDecimal("500"),  new BigDecimal("2500"),
            new BigDecimal("4000")
        };

        RangeSumService service = new RangeSumService(daily);  // O(n) preprocessing

        log.info("Total spent from day 2 to day 5 (inclusive)");
        log.info("Sum -> Rs." + service.rangeSum(2, 5));       // O(1)

        log.info("Total spent from day 0 to day 6 (whole week)");
        log.info("Sum -> Rs." + service.rangeSum(0, 6));       // O(1)

        log.info("Total spent on day 3 alone");
        log.info("Sum -> Rs." + service.rangeSum(3, 3));       // O(1)
    }
}

// ─── Would be in service/RangeSumService.java ───
class RangeSumService {
    private final BigDecimal[] prefix;  // prefix[i] = sum of first i elements

    RangeSumService(BigDecimal[] arr) {
        // Build prefix array with a leading zero. O(n).
        prefix = new BigDecimal[arr.length + 1];
        prefix[0] = BigDecimal.ZERO;
        for (int i = 0; i < arr.length; i++) {
            prefix[i + 1] = prefix[i].add(arr[i]);  // exact money addition
        }
    }

    // Inclusive range sum left..right in O(1).
    BigDecimal rangeSum(int left, int right) {
        return prefix[right + 1].subtract(prefix[left]);
    }
}

// ─── Would be in util/BankLogFormatter.java ───
class BankLogFormatter extends java.util.logging.Formatter {
    @Override
    public String format(java.util.logging.LogRecord record) {
        return String.format("%1$tF %1$tT [%2$s] %3$s%n",
            new java.util.Date(record.getMillis()),
            record.getLevel().getName(),
            record.getMessage());
    }
}
